#include <metal_stdlib>
using namespace metal;

struct ShaderUniforms {
    float4 resolutionTime;
    float4 mouse;
};

float hash21(float2 p) {
    p = fract(p * float2(0.1031, 0.1030));
    p += dot(p, p.yx + 33.33);
    return fract((p.x + p.y) * p.x);
}

float hash31(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.yzx + 33.33);
    return fract((p.x + p.y) * p.z);
}

float noise3(float3 p) {
    float3 cell = floor(p);
    float3 f = fract(p);
    float3 u = f * f * (3.0 - 2.0 * f);
    float a = mix(hash31(cell), hash31(cell + float3(1.0, 0.0, 0.0)), u.x);
    float b = mix(hash31(cell + float3(0.0, 1.0, 0.0)),
                  hash31(cell + float3(1.0, 1.0, 0.0)), u.x);
    float c = mix(hash31(cell + float3(0.0, 0.0, 1.0)),
                  hash31(cell + float3(1.0, 0.0, 1.0)), u.x);
    float d = mix(hash31(cell + float3(0.0, 1.0, 1.0)),
                  hash31(cell + float3(1.0, 1.0, 1.0)), u.x);
    return mix(mix(a, b, u.y), mix(c, d, u.y), u.z);
}

float cloudDensity(float3 p, float time, bool fineDetail) {
    float3 q = p * float3(0.42, 0.74, 0.42)
               + float3(0.23 * time, 0.04 * sin(0.35 * time), 0.38 * time);
    float shape = 0.62 * noise3(q * 0.62)
                  + 0.28 * noise3(q * 1.51)
                  + 0.10 * (fineDetail ? noise3(q * 3.07) : 0.5);
    float floorFade = smoothstep(-1.9, -0.9, p.y);
    float ceilingFade = 1.0 - smoothstep(0.35, 1.5, p.y);
    return smoothstep(0.50, 0.66, shape) * floorFade * ceilingFade;
}

float3 skyColor(float3 rd, float3 sunDir) {
    float height = smoothstep(-0.15, 0.8, rd.y);
    float3 sky = mix(float3(0.37, 0.60, 0.81),
                     float3(0.09, 0.30, 0.68), height);
    float horizon = exp(-7.0 * abs(rd.y));
    sky = mix(sky, float3(0.89, 0.60, 0.38), 0.20 * horizon);
    float sun = max(dot(rd, sunDir), 0.0);
    sky += float3(1.0, 0.72, 0.46) * (0.16 * pow(sun, 16.0)
                                      + 0.55 * pow(sun, 512.0));
    return sky;
}

float3 renderClouds(float3 ro, float3 rd, float2 pixel, float time) {
    const float3 sunDir = normalize(float3(-0.52, 0.58, 0.62));
    float3 sky = skyColor(rd, sunDir);
    float nearDistance = 0.0;
    float farDistance = 55.0;

    if (abs(rd.y) < 0.0001) {
        if (ro.y < -1.9 || ro.y > 1.5) return sky;
    } else {
        float lower = (-1.9 - ro.y) / rd.y;
        float upper = (1.5 - ro.y) / rd.y;
        nearDistance = max(0.0, min(lower, upper));
        farDistance = min(farDistance, max(lower, upper));
    }

    if (farDistance <= nearDistance) return sky;

    float4 accumulated = float4(0.0);
    float t = nearDistance
              + hash21(floor(pixel)) * (0.16 + 0.025 * nearDistance);

    for (int step = 0; step < 80; ++step) {
        if (t >= farDistance || accumulated.a > 0.995) break;
        float dt = min(0.16 + 0.025 * t, farDistance - t);
        float3 position = ro + (t + 0.5 * dt) * rd;
        float density = cloudDensity(position, time, t < 18.0);
        if (density > 0.005) {
            float litDensity = cloudDensity(position + 0.65 * sunDir,
                                            time, false);
            float light = clamp(0.54 + 2.2 * (density - litDensity),
                                0.16, 1.0);
            float3 cloud = mix(float3(0.13, 0.21, 0.32),
                               float3(0.87, 0.88, 0.86), light);
            cloud = mix(cloud, sky, 1.0 - exp(-0.0007 * t * t));
            float alpha = 1.0 - exp(-0.78 * density * dt);
            float visible = (1.0 - accumulated.a) * alpha;
            accumulated.rgb += cloud * visible;
            accumulated.a += visible;
        }
        t += dt;
    }

    return sky * (1.0 - accumulated.a) + accumulated.rgb;
}

vertex float4 fullscreenVertex(uint vertexID [[vertex_id]]) {
    float2 p = float2((vertexID << 1) & 2, vertexID & 2);
    return float4(p * 2.0 - 1.0, 0.0, 1.0);
}

fragment float4 cloudyFragment(
    float4 position [[position]],
    constant ShaderUniforms &uniforms [[buffer(0)]]) {
    float2 resolution = uniforms.resolutionTime.xy;
    float2 frag = float2(position.x, resolution.y - position.y);
    float2 uv = (2.0 * frag - resolution) / resolution.y;
    float time = uniforms.resolutionTime.z;
    float2 pointer = uniforms.mouse.xy / resolution;
    float azimuth = 0.55 * (pointer.x - 0.5) + 0.035 * sin(0.11 * time);
    float elevation = 0.4 * (pointer.y - 0.5);
    float3 ro = float3(5.0 * sin(azimuth), 2.2 + elevation,
                        -6.0 * cos(azimuth));
    float3 target = float3(0.0, -0.15, 6.0);
    float3 forward = normalize(target - ro);
    float3 right = normalize(cross(float3(0.0, 1.0, 0.0), forward));
    float3 up = cross(forward, right);
    float3 rd = normalize(uv.x * right + uv.y * up + 1.45 * forward);
    float3 linear = renderClouds(ro, rd, frag, time);
    return float4(clamp(linear, float3(0.0), float3(1.0)), 1.0);
}
